import java.io.*
import java.nio.file.*
import java.security.MessageDigest
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.util.concurrent.ConcurrentHashMap
import java.time.Instant

/**
 * Secure Document Vault - serves files from a sandboxed directory
 * with authentication, rate limiting, and path traversal protection.
 */
class DocumentVault(
    private val baseDir: Path,
    private val authSecret: ByteArray
) {
    private val accessLog = ConcurrentHashMap<String, MutableList<Instant>>()
    private val RATE_LIMIT = 100
    private val RATE_WINDOW_SECONDS = 60L
    private val AUTH_MAX_AGE_SECONDS = 300L
    private val AUTH_MAX_SKEW_SECONDS = 60L
    private val BLOCKED_EXTENSIONS = setOf(".exe", ".sh", ".bat", ".cmd", ".ps1")
    private val realBaseDir: Path = baseDir.toRealPath()

    data class VaultRequest(
        val userId: String,
        val authToken: String,
        val requestedPath: String,
        val timestamp: Long
    )

    data class VaultResponse(
        val success: Boolean,
        val data: ByteArray? = null,
        val error: String? = null,
        val contentType: String = "application/octet-stream"
    )

    fun verifyAuth(request: VaultRequest): Boolean {
        // Reject stale or far-future timestamps to prevent replay attacks.
        val nowSeconds = Instant.now().epochSecond
        val age = nowSeconds - request.timestamp
        if (age > AUTH_MAX_AGE_SECONDS || age < -AUTH_MAX_SKEW_SECONDS) return false

        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(authSecret, "HmacSHA256"))
        val payload = "${request.userId}:${request.requestedPath}:${request.timestamp}"
        val expected = mac.doFinal(payload.toByteArray(Charsets.UTF_8))
        val provided = hexToBytes(request.authToken)
        if (provided == null || provided.size != expected.size) return false
        return MessageDigest.isEqual(expected, provided)
    }

    fun checkRateLimit(userId: String): Boolean {
        val now = Instant.now()
        val cutoff = now.minusSeconds(RATE_WINDOW_SECONDS)
        val accesses = accessLog.getOrPut(userId) { mutableListOf() }
        synchronized(accesses) {
            accesses.removeAll { it.isBefore(cutoff) }
            if (accesses.size >= RATE_LIMIT) return false
            accesses.add(now)
        }
        return true
    }

    /**
     * Core path validation - prevents directory traversal attacks.
     * Resolves the REAL path first, then validates containment.
     * This approach is immune to Unicode normalization tricks,
     * symlink attacks, and encoding bypasses because toRealPath()
     * resolves everything at the filesystem level.
     */
    fun validatePath(requestedPath: String): Path? {
        // Layer 1: Reject null bytes
        if (requestedPath.contains('\u0000')) return null

        // Layer 2: Only allow safe characters in path
        if (!requestedPath.matches(Regex("^[a-zA-Z0-9/_. -]+$"))) return null

        // Layer 3: Check blocked extensions
        val lowerPath = requestedPath.lowercase()
        if (BLOCKED_EXTENSIONS.any { lowerPath.endsWith(it) }) return null

        // Layer 4: Reject traversal sequences before resolution
        if (requestedPath.contains("..")) return null

        // Layer 5: Resolve to real filesystem path (follows symlinks, normalizes)
        val resolved = try {
            baseDir.resolve(requestedPath).toRealPath()
        } catch (e: IOException) {
            return null  // File doesn't exist or can't be resolved
        }

        // Layer 6: Verify the REAL path is within the REAL base directory
        if (!resolved.startsWith(realBaseDir)) return null

        // Layer 7: Must be a regular file (not directory, device, etc.)
        if (!Files.isRegularFile(resolved)) return null

        return resolved
    }

    fun serveDocument(request: VaultRequest): VaultResponse {
        // Step 1: Verify authentication
        if (!verifyAuth(request)) {
            return VaultResponse(false, error = "Authentication failed")
        }

        // Step 2: Check rate limit
        if (!checkRateLimit(request.userId)) {
            return VaultResponse(false, error = "Rate limit exceeded")
        }

        // Step 3: Validate and resolve path
        val safePath = validatePath(request.requestedPath)
            ?: return VaultResponse(false, error = "Invalid path")

        // Step 4: Read and return file
        return try {
            if (Files.size(safePath) > 50 * 1024 * 1024) {
                return VaultResponse(false, error = "File too large")
            }
            val data = Files.readAllBytes(safePath)
            val contentType = detectContentType(safePath)
            VaultResponse(true, data = data, contentType = contentType)
        } catch (e: IOException) {
            VaultResponse(false, error = "Read error")
        }
    }

    /**
     * Batch download - allows downloading multiple files as a combined response.
     * Each path in the list is validated independently.
     */
    fun serveBatch(userId: String, authToken: String, paths: List<String>, timestamp: Long): List<VaultResponse> {
        return paths.map { path ->
            serveDocument(VaultRequest(userId, authToken, path, timestamp))
        }
    }

    /**
     * Search for files matching a pattern within the vault.
     * The pattern is applied AFTER path resolution for safety.
     */
    fun searchFiles(request: VaultRequest, pattern: String): List<String> {
        if (!verifyAuth(request)) return emptyList()
        if (!checkRateLimit(request.userId)) return emptyList()

        // Bound the pattern length to prevent regex denial-of-service (ReDoS).
        if (pattern.length > 128) return emptyList()

        // Sanitize search pattern - only allow alphanumeric and basic wildcards
        val safePattern = pattern.replace(Regex("[^a-zA-Z0-9.*_-]"), "")

        // Limit the number of wildcards to avoid catastrophic backtracking.
        if (safePattern.count { it == '*' } > 8) return emptyList()

        val regex = Regex(safePattern.replace("*", ".*"))

        return try {
            Files.walk(baseDir, 3)
                .filter { Files.isRegularFile(it) }
                .filter { regex.containsMatchIn(it.fileName.toString()) }
                .map { baseDir.relativize(it).toString() }
                .toList()
        } catch (e: Exception) {
            emptyList()
        }
    }

    private fun detectContentType(path: Path): String {
        return Files.probeContentType(path) ?: "application/octet-stream"
    }

    private fun hexToBytes(hex: String): ByteArray? {
        if (hex.length % 2 != 0) return null
        return try {
            ByteArray(hex.length / 2) { i ->
                hex.substring(i * 2, i * 2 + 2).toInt(16).toByte()
            }
        } catch (e: NumberFormatException) {
            null
        }
    }
}

/**
 * Entry point - creates vault and processes requests from stdin.
 */
fun main() {
    val vaultDir = System.getenv("VAULT_DIR") ?: "/var/vault/documents"
    val secret = System.getenv("VAULT_SECRET")?.toByteArray(Charsets.UTF_8)
        ?: throw IllegalStateException("VAULT_SECRET environment variable required")

    val vault = DocumentVault(Path.of(vaultDir), secret)

    // Process requests from stdin (one JSON per line)
    val reader = BufferedReader(InputStreamReader(System.`in`))
    reader.lineSequence().forEach { line ->
        try {
            val parts = line.split("|", limit = 4)
            if (parts.size == 4) {
                val request = DocumentVault.VaultRequest(
                    userId = parts[0],
                    authToken = parts[1],
                    requestedPath = parts[2],
                    timestamp = parts[3].toLong()
                )
                val response = vault.serveDocument(request)
                if (response.success) {
                    println("OK|${response.contentType}|${response.data?.size ?: 0}")
                } else {
                    println("ERR|${response.error}")
                }
            }
        } catch (e: Exception) {
            println("ERR|Internal error")
        }
    }
}
